BEGIN;
DO $$ DECLARE a int;q int;b numeric;x int;d numeric; BEGIN SELECT pp.id_prestamo,pp.numero_cuota,pp.monto_pagado INTO a,q,b FROM prestamos.plan_pagos pp WHERE pp.monto_pagado<pp.monto_programado ORDER BY pp.id_prestamo,pp.numero_cuota LIMIT 1;x:=prestamos.registrar_pago_san(a,q,1,current_date,'Prueba SAN');UPDATE prestamos.pagos SET numero_cuota=q WHERE id_pago=x;PERFORM prestamos.anular_pago(x,'Prueba automatizada SAN','Codex');SELECT monto_pagado INTO d FROM prestamos.plan_pagos WHERE id_prestamo=a AND numero_cuota=q;IF d<>b OR (SELECT estado FROM prestamos.pagos WHERE id_pago=x)<>'ANULADO' THEN RAISE EXCEPTION 'Falló SAN';END IF;RAISE NOTICE 'SAN_OK';END $$;
DO $$ DECLARE a int;b numeric;x int;d numeric; BEGIN SELECT p.id_prestamo,p.capital_pendiente INTO a,b FROM prestamos.prestamos p JOIN prestamos.tipos_prestamo t ON t.id_tipo_prestamos=p.id_tipo_prestamos WHERE t.nombre='REDITO' AND p.capital_pendiente>=2 LIMIT 1;x:=prestamos.registrar_pago_redito(a,1,current_date,'Prueba redido');PERFORM prestamos.anular_pago(x,'Prueba automatizada redido','Codex');SELECT capital_pendiente INTO d FROM prestamos.prestamos WHERE id_prestamo=a;IF d<>b OR (SELECT estado FROM prestamos.pagos WHERE id_pago=x)<>'ANULADO' THEN RAISE EXCEPTION 'Falló REDITO';END IF;RAISE NOTICE 'REDITO_OK';END $$;
DO $$ DECLARE a int;b numeric;x int;d numeric; BEGIN SELECT p.id_prestamo,p.capital_pendiente INTO a,b FROM prestamos.prestamos p JOIN prestamos.tipos_prestamo t ON t.id_tipo_prestamos=p.id_tipo_prestamos WHERE t.nombre='REDITO' AND p.capital_pendiente>=2 LIMIT 1;x:=prestamos.registrar_abono_capital(a,1,current_date,'Prueba capital');PERFORM prestamos.anular_pago(x,'Prueba automatizada capital','Codex');SELECT capital_pendiente INTO d FROM prestamos.prestamos WHERE id_prestamo=a;IF d<>b OR (SELECT estado FROM prestamos.pagos WHERE id_pago=x)<>'ANULADO' THEN RAISE EXCEPTION 'Falló CAPITAL';END IF;RAISE NOTICE 'CAPITAL_OK';END $$;
DO $$ DECLARE a int;b numeric;x int;d numeric; BEGIN SELECT p.id_prestamo,p.capital_pendiente INTO a,b FROM prestamos.prestamos p JOIN prestamos.tipos_prestamo t ON t.id_tipo_prestamos=p.id_tipo_prestamos WHERE t.nombre='REDITO' AND p.capital_pendiente>=2 LIMIT 1;x:=prestamos.registrar_pago_mixto(a,1,1,current_date,'Prueba mixta');PERFORM prestamos.anular_pago(x,'Prueba automatizada mixta','Codex');SELECT capital_pendiente INTO d FROM prestamos.prestamos WHERE id_prestamo=a;IF d<>b OR (SELECT estado FROM prestamos.pagos WHERE id_pago=x)<>'ANULADO' THEN RAISE EXCEPTION 'Falló MIXTO';END IF;RAISE NOTICE 'MIXTO_OK';END $$;
ROLLBACK;
